@Test
public void testResourceFormatting() {
    ResourcesFormattingSubject res = ResourcesFactory.get(ResourcesFormattingSubject.class);
    assertThat(res.withoutAnnotationsOrParameters(), equalTo("withoutAnnotationsOrParameters"));
    assertThat(res.withAnnotationWithoutPatternOneParam(42), equalTo("withAnnotationWithoutPatternOneParam(\"42\")"));
    assertThat(res.withAnnotationWithPatternOneParam(72), equalTo("before72after"));
    assertThat(res.withAnnotationWithSimplePatternOneParam(33), equalTo("33"));
    assertThat(res.withoutAnnotationsWithElevenParams("v1", "v2", "v3", "v4", "v5", "v6", "v7", "v8", "v9", "v10", "v11"), equalTo("withoutAnnotationsWithElevenParams(\"v1\",\"v2\",\"v3\",\"v4\",\"v5\",\"v6\",\"v7\",\"v8\",\"v9\",\"v10\",\"v11\")"));
    assertThat(res.withoutAnnotationsWithOneParam(17), equalTo("withoutAnnotationsWithOneParam(\"17\")"));
    assertThat(res.withMoreFormatParamsThanMethodParams(7), equalTo("7,{1}"));
    assertThat(res.withLessFormatParamsThanMethodParams(7, 11), equalTo("7"));
}

