@Test
public void testCreateServiceConfigActive() {
    HaServiceConfig serviceConfig = HaDescriptorFactory.createServiceConfig("foo", "enableStickySession=true;enabled=true;maxFailoverAttempts=42;failoverSleep=50");
    assertNotNull(serviceConfig);
    assertTrue(serviceConfig.isEnabled());
    assertEquals("foo", serviceConfig.getServiceName());
    assertEquals(42, serviceConfig.getMaxFailoverAttempts());
    assertEquals(50, serviceConfig.getFailoverSleep());
    assertTrue(serviceConfig.isStickySessionEnabled());
    assertEquals(HaServiceConfigConstants.DEFAULT_STICKY_SESSION_COOKIE_NAME, serviceConfig.getStickySessionCookieName());
    serviceConfig = HaDescriptorFactory.createServiceConfig("foo", "enableStickySession=true;enabled=true;maxFailoverAttempts=42;failoverSleep=50;stickySessionCookieName=abc");
    assertNotNull(serviceConfig);
    assertTrue(serviceConfig.isEnabled());
    assertEquals("foo", serviceConfig.getServiceName());
    assertEquals(42, serviceConfig.getMaxFailoverAttempts());
    assertEquals(50, serviceConfig.getFailoverSleep());
    assertTrue(serviceConfig.isStickySessionEnabled());
    assertEquals("abc", serviceConfig.getStickySessionCookieName());
    serviceConfig = HaDescriptorFactory.createServiceConfig("bar", "false", "3", "1000", null, null, null, "true", null, null, null);
    assertNotNull(serviceConfig);
    assertFalse(serviceConfig.isEnabled());
    assertEquals("bar", serviceConfig.getServiceName());
    assertEquals(3, serviceConfig.getMaxFailoverAttempts());
    assertEquals(1000, serviceConfig.getFailoverSleep());
    assertTrue(serviceConfig.isStickySessionEnabled());
    assertEquals(HaServiceConfigConstants.DEFAULT_STICKY_SESSION_COOKIE_NAME, serviceConfig.getStickySessionCookieName());
    serviceConfig = HaDescriptorFactory.createServiceConfig("knox", "false", "4", "3000", null, null, null, null, null, null, null);
    assertNotNull(serviceConfig);
    assertFalse(serviceConfig.isEnabled());
    assertEquals("knox", serviceConfig.getServiceName());
    assertEquals(4, serviceConfig.getMaxFailoverAttempts());
    assertEquals(3000, serviceConfig.getFailoverSleep());
    assertFalse(serviceConfig.isStickySessionEnabled());
    assertEquals(HaServiceConfigConstants.DEFAULT_STICKY_SESSION_COOKIE_NAME, serviceConfig.getStickySessionCookieName());
    serviceConfig = HaDescriptorFactory.createServiceConfig("bar", "false", "3", "1000", null, null, null, "true", "abc", null, null);
    assertNotNull(serviceConfig);
    assertFalse(serviceConfig.isEnabled());
    assertEquals("bar", serviceConfig.getServiceName());
    assertEquals(3, serviceConfig.getMaxFailoverAttempts());
    assertEquals(1000, serviceConfig.getFailoverSleep());
    assertTrue(serviceConfig.isStickySessionEnabled());
    assertEquals("abc", serviceConfig.getStickySessionCookieName());
    serviceConfig = HaDescriptorFactory.createServiceConfig("bar", "false", "3", "1000", null, null, "true", null, "abc", "true", null);
    assertNotNull(serviceConfig);
    assertFalse(serviceConfig.isEnabled());
    assertEquals("bar", serviceConfig.getServiceName());
    assertEquals(3, serviceConfig.getMaxFailoverAttempts());
    assertEquals(1000, serviceConfig.getFailoverSleep());
    assertFalse(serviceConfig.isStickySessionEnabled());
    assertTrue(serviceConfig.isLoadBalancingEnabled());
    assertTrue(serviceConfig.isNoFallbackEnabled());
    assertEquals("abc", serviceConfig.getStickySessionCookieName());
}

@Test
public void testDescriptorLoad() throws IOException {
    String xml = "<ha><service name='foo' maxFailoverAttempts='42' failoverSleep='4000' enabled='false'/>" + "<service name='bar' failoverLimit='3' enabled='true'/></ha>";
    ByteArrayInputStream inputStream = new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8));
    HaDescriptor descriptor = HaDescriptorManager.load(inputStream);
    assertNotNull(descriptor);
    assertEquals(1, descriptor.getEnabledServiceNames().size());
    HaServiceConfig config = descriptor.getServiceConfig("foo");
    assertNotNull(config);
    assertEquals("foo", config.getServiceName());
    assertEquals(42, config.getMaxFailoverAttempts());
    assertEquals(4000, config.getFailoverSleep());
    assertFalse(config.isEnabled());
    assertFalse(config.isStickySessionEnabled());
    assertFalse(config.isNoFallbackEnabled());
    config = descriptor.getServiceConfig("bar");
    assertTrue(config.isEnabled());
}

