@Test
public void testDeployment() {
    WebArchive webArchive = ShrinkWrap.create(WebArchive.class, "test-archive");
    final String CUSTOM_IMPERSONATION_PARAM = "impersonationParam";
    Provider provider = new Provider();
    provider.setEnabled(true);
    provider.setName(MockAbstractIdentityAsserterDeploymentContributor.NAME);
    Service service = new Service();
    Map<String, String> params = new HashMap<>();
    params.put(IMPERSONATION_PARAMS, CUSTOM_IMPERSONATION_PARAM);
    service.setParams(params);
    Topology topology = new Topology();
    topology.setName("Sample");
    GatewayDescriptor gatewayDescriptor = new GatewayDescriptorImpl();
    ResourceDescriptor resource = gatewayDescriptor.createResource();
    DeploymentContext context = EasyMock.createNiceMock(DeploymentContext.class);
    EasyMock.expect(context.getWebArchive()).andReturn(webArchive).anyTimes();
    EasyMock.expect(context.getTopology()).andReturn(topology).anyTimes();
    EasyMock.expect(context.getGatewayDescriptor()).andReturn(gatewayDescriptor).anyTimes();
    EasyMock.replay(context);
    AbstractIdentityAsserterDeploymentContributor contributor = new MockAbstractIdentityAsserterDeploymentContributor();
    contributor.initializeContribution(context);
    contributor.contributeFilter(context, provider, service, resource, null);
    contributor.finalizeContribution(context);
    FilterDescriptor identityFilterDescriptor = resource.filters().get(0);
    List<FilterParamDescriptor> filterParams = identityFilterDescriptor.params();
    assertEquals(1, filterParams.size());
    FilterParamDescriptor paramDescriptor = filterParams.get(0);
    assertEquals(IMPERSONATION_PARAMS, paramDescriptor.name());
    assertEquals(CUSTOM_IMPERSONATION_PARAM, paramDescriptor.value());
}

@Test
public void testSimpleFilter() throws ServletException, IOException {
    ServletContext servletContext = createMock(ServletContext.class);
    EasyMock.expect(servletContext.getAttribute(GatewayServices.GATEWAY_CLUSTER_ATTRIBUTE)).andReturn("topology1").anyTimes();
    servletContext.setAttribute(ContextAttributes.IMPERSONATION_ENABLED_ATTRIBUTE, Boolean.FALSE);
    EasyMock.expectLastCall();
    EasyMock.replay(servletContext);
    FilterConfig config = EasyMock.createNiceMock(FilterConfig.class);
    EasyMock.expect(config.getServletContext()).andReturn(servletContext).anyTimes();
    EasyMock.expect(config.getInitParameter(CommonIdentityAssertionFilter.GROUP_PRINCIPAL_MAPPING)).andReturn("*=everyone;lmccay=test-virtual-group").once();
    EasyMock.expect(config.getInitParameter(CommonIdentityAssertionFilter.PRINCIPAL_MAPPING)).andReturn("ljm=lmccay;").once();
    EasyMock.expect(config.getInitParameterNames()).andReturn(Collections.enumeration(Arrays.asList(CommonIdentityAssertionFilter.GROUP_PRINCIPAL_MAPPING, CommonIdentityAssertionFilter.PRINCIPAL_MAPPING, CommonIdentityAssertionFilter.VIRTUAL_GROUP_MAPPING_PREFIX + "test-virtual-group", // invalid group with no name
    CommonIdentityAssertionFilter.VIRTUAL_GROUP_MAPPING_PREFIX))).anyTimes();
    EasyMock.expect(config.getInitParameter(IMPERSONATION_PARAMS)).andReturn("doAs").anyTimes();
    EasyMock.expect(config.getInitParameter(CommonIdentityAssertionFilter.VIRTUAL_GROUP_MAPPING_PREFIX + "test-virtual-group")).andReturn("(and (username 'lmccay') (and (member 'users') (member 'admin')))").anyTimes();
    EasyMock.expect(config.getInitParameter(CommonIdentityAssertionFilter.VIRTUAL_GROUP_MAPPING_PREFIX)).andReturn("true").anyTimes();
    EasyMock.replay(config);
    final HttpServletRequest request = EasyMock.createNiceMock(HttpServletRequest.class);
    EasyMock.replay(request);
    final HttpServletResponse response = EasyMock.createNiceMock(HttpServletResponse.class);
    EasyMock.replay(response);
    final FilterChain chain = (req, resp) -> {
    };
    Subject subject = new Subject();
    subject.getPrincipals().add(new PrimaryPrincipal("ljm"));
    subject.getPrincipals().add(new GroupPrincipal("users"));
    subject.getPrincipals().add(new GroupPrincipal("admin"));
    try {
        Subject.doAs(subject, (PrivilegedExceptionAction<Object>) () -> {
            filter.init(config);
            filter.doFilter(request, response, chain);
            return null;
        });
    } catch (PrivilegedActionException e) {
        Throwable t = e.getCause();
        if (t instanceof IOException) {
            throw (IOException) t;
        } else if (t instanceof ServletException) {
            throw (ServletException) t;
        } else {
            throw new ServletException(t);
        }
    }
    assertEquals("LMCCAY", username);
    assertTrue("Should be greater than 2", calculatedGroups.size() > 2);
    assertTrue(calculatedGroups.containsAll(Arrays.asList("everyone", "USERS", "ADMIN", "test-virtual-group")));
    assertFalse(calculatedGroups.contains(""));
}

