    rule = config.getRules().get(0);
    assertThat(rule, notNullValue());
    assertThat(rule.name(), nullValue());
    assertThat(rule.pattern(), is("test-pattern"));
    assertThat(rule.directions(), nullValue());
    assertThat(rule.flow(), nullValue());
