@Test
public void testAddStartAndStop() throws ServiceLifecycleException {
    AbstractGatewayServices gatewayServices = createMockBuilder(AbstractGatewayServices.class).withConstructor("role", "name").createMock();
    Map<ServiceType, Service> serviceMap = new EnumMap<>(ServiceType.class);
    TestService lastService = null;
    ServiceType[] orderedServiceTypes = { ServiceType.MASTER_SERVICE, ServiceType.KEYSTORE_SERVICE, ServiceType.ALIAS_SERVICE, ServiceType.SSL_SERVICE, ServiceType.TOKEN_STATE_SERVICE, ServiceType.TOKEN_SERVICE, ServiceType.SERVER_INFO_SERVICE, ServiceType.REMOTE_REGISTRY_CLIENT_SERVICE, ServiceType.CLUSTER_CONFIGURATION_MONITOR_SERVICE, ServiceType.TOPOLOGY_SERVICE, ServiceType.METRICS_SERVICE, ServiceType.CRYPTO_SERVICE, ServiceType.HOST_MAPPING_SERVICE, ServiceType.SERVICE_DEFINITION_REGISTRY, ServiceType.SERVICE_REGISTRY_SERVICE, ServiceType.CONCURRENT_SESSION_VERIFIER, ServiceType.REMOTE_CONFIGURATION_MONITOR, ServiceType.GATEWAY_STATUS_SERVICE };
    assertNotEquals(ServiceType.values(), orderedServiceTypes);
    // Services should be started in the order they were added.. and stopped in the reverse order.
    // For testing let's use an order different than what is defined in the ServiceType enum.
    for (ServiceType serviceType : orderedServiceTypes) {
        TestService testService = new TestService();
        testService.setPreviousService(lastService);
        if (lastService != null) {
            lastService.setNextService(testService);
        }
        lastService = testService;
        serviceMap.put(serviceType, testService);
        gatewayServices.addService(serviceType, serviceMap.get(serviceType));
    }
    gatewayServices.start();
    gatewayServices.stop();
    assertEquals(EnumSet.allOf(ServiceType.class), gatewayServices.getServiceTypes());
}

