@Test
public void testOnWebSocketConnect() throws Exception {
    GatewayConfig gatewayConfig = setupGatewayConfig();
    setupMessagesFactory();
    setupAuditor();
    JWTValidator jwtValidator = EasyMock.createNiceMock(JWTValidator.class);
