    Assert.assertTrue("Failed to match whitelist", RegExUtils.checkBaseUrlAgainstWhitelist("^https?:\\/\\/(.*KNOX_GW_DOMAIN)(?::[0-9]+)?(?:\\/.*)?$", "https://KNOX_GW_DOMAIN?a=1&b=2"));
    Assert.assertTrue("Failed to match whitelist", RegExUtils.checkBaseUrlAgainstWhitelist("^https?:\\/\\/(.*KNOX_GW_DOMAIN)(?::[0-9]+)?(?:\\/.*)?$", "https://KNOX_GW_DOMAIN?a=1&b=2"));
