@Test(timeout = TestUtils.LONG_TIMEOUT)
public void testCLIServiceTest() throws Exception {
    LOG_ENTER();
    setupResources();
    InetSocketAddress gatewayAddress = driver.gateway.getAddresses()[0];
    String gatewayPort = Integer.toString(gatewayAddress.getPort());
    //    Now let's make sure we can run this same command from the CLI.
    PrintStream out = System.out;
    final ByteArrayOutputStream outContent = new ByteArrayOutputStream();
    System.setOut(new PrintStream(outContent, false, StandardCharsets.UTF_8.name()));
    String[] args = { "service-test", "--master", "knox", "--cluster", driver.clusterName, "--hostname", gatewayAddress.getHostName(), "--port", gatewayPort, "--u", "kminder", "--p", "kminder-password" };
    KnoxCLI cli = new KnoxCLI();
    cli.run(args);
    Assume.assumeTrue("Gateway port should not contain status code", !gatewayPort.contains("404") && !gatewayPort.contains("403"));
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), not(containsString("\"httpCode\": 401")));
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), not(containsString("404")));
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), not(containsString("403")));
    outContent.reset();
    setupResources();
    String[] args2 = { "service-test", "--master", "knox", "--cluster", driver.clusterName, "--hostname", gatewayAddress.getHostName(), "--port", gatewayPort };
    cli = new KnoxCLI();
    cli.run(args2);
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), (containsString("Username and/or password not supplied. Expect HTTP 401 Unauthorized responses.")));
    outContent.reset();
    String[] args3 = { "service-test", "--master", "knox", "--cluster", driver.clusterName, "--hostname", "bad-host", "--port", "0", "--u", "guest", "--p", "guest-password" };
    cli = new KnoxCLI();
    cli.run(args3);
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()).toLowerCase(Locale.ROOT), either(containsString("nodename nor servname provided")).or(containsString("name or service not known")).or(containsString("//bad-host:0/")));
    outContent.reset();
    String[] args4 = { "service-test", "--master", "knox", "--cluster", driver.clusterName, "--hostname", gatewayAddress.getHostName(), "--port", "543", "--u", "mapred", "--p", "mapred-password" };
    cli = new KnoxCLI();
    cli.run(args4);
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), containsString("failed: Connection refused"));
    outContent.reset();
    String[] args5 = { "service-test", "--master", "knox", "--hostname", gatewayAddress.getHostName(), "--port", "543", "--u", "mapred", "--p", "mapred-password" };
    cli = new KnoxCLI();
    cli.run(args5);
    assertThat(outContent.toString(StandardCharsets.UTF_8.name()), containsString("--cluster argument is required"));
    outContent.reset();
    //    Reset the out content
    System.setOut(out);
    LOG_EXIT();
}

