    actualInput = new URI("https://localhost:8443/gateway/oozieui/oozie/v2/jobs?_dc=1438899557070&filter=&timezone=GMT");
    actualOutput = Rewriter.rewrite(actualInput, inputTemplate, outputTemplate, null, null);
