    assertThat(output, is(input));
    input = "{}";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    // {X}
    // *
    // **
    // {*}
    // {**}
    input = "*,${";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "$";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "$$";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "*,$";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "*.,${";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "{";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
    input = "}";
    template = Parser.parseTemplate(input);
    output = template.toString();
    assertThat(output, is(input));
